import{_ as l,C as n,o as p,c as i,j as r,a as t,E as e,a2 as o}from"./chunks/framework.B-bxTAy7.js";const C=JSON.parse('{"title":"学习地图：从看懂电路到做出东西","description":"电学手记的学习地图：0–7 八个阶段，每个阶段写清学什么、在哪个页面、大约多久、过关标准，另附考试速通 / 系统学 / 做项目三条路线、每阶段的前置检查与卡住时的去处，文末一张「我该从哪开始」决策表。","frontmatter":{"title":"学习地图：从看懂电路到做出东西","description":"电学手记的学习地图：0–7 八个阶段，每个阶段写清学什么、在哪个页面、大约多久、过关标准，另附考试速通 / 系统学 / 做项目三条路线、每阶段的前置检查与卡住时的去处，文末一张「我该从哪开始」决策表。","outline":[2,3]},"headers":[],"relativePath":"map.md","filePath":"map.md","lastUpdated":1792603101000}'),h={name:"map.md"};function g(f,a,m,u,c,b){const d=n("Meta"),s=n("Prereq");return p(),i("div",null,[a[22]||(a[22]=r("h1",{id:"学习地图-从看懂电路到做出东西",tabindex:"-1"},[t("学习地图：从看懂电路到做出东西 "),r("a",{class:"header-anchor",href:"#学习地图-从看懂电路到做出东西","aria-label":'Permalink to "学习地图：从看懂电路到做出东西"'},"​")],-1)),e(d,{time:"12 min",level:"指南",note:"先看这张地图再决定读哪一页：八个阶段、三条路线、每阶段的过关标准与卡住时的去处"}),a[23]||(a[23]=o(`<p>站里现在有四门课、一个实验板块、一组项目专题，加起来一百多页。页面各写各的时候，最常出现的困局是两种：一种是「四门课都翻过，却说不清哪门该先读」；另一种更隐蔽——按顺序读完了，手还是不敢碰面包板。<strong>这份地图就是把它们重新排成一条线：先读到能算，再动手验证，最后做出一个能打开的东西。</strong></p><p>读完这一页大约 12 分钟。它不给推导，只回答四件事：你现在在哪、下一步读哪一页、要花多久、怎么知道自己过关了。</p><h2 id="结论先行-一条主线与三条岔路" tabindex="-1">结论先行：一条主线与三条岔路 <a class="header-anchor" href="#结论先行-一条主线与三条岔路" aria-label="Permalink to &quot;结论先行：一条主线与三条岔路&quot;">​</a></h2><p>八个阶段的主干是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 电学入门与安全  →  1 电工学  →  2 数字电路  →  3 模拟电子  →  4 嵌入式 STM32</span></span>
<span class="line"><span>                      （电路定律到三相/电机）                        │</span></span>
<span class="line"><span>                                                        5 实验与仪器（可与 4 并行）</span></span>
<span class="line"><span>                                                                     │</span></span>
<span class="line"><span>                                  6 项目专题（电源 → 电机驱动 → 舵机云台）</span></span>
<span class="line"><span>                                                                     │</span></span>
<span class="line"><span>                                                        7 电力电子与进阶</span></span></code></pre></div><p>两个容易看错的地方先说清楚：</p><ol><li><strong>阶段 5 不是阶段 4 的后续，而是它的同行者。</strong> 实验板块讲的是万用表、示波器、焊接与实验台，这些东西在你读阶段 1 时就能开始练，不必等到学完中断和 RTOS 才去买表。地图上把它画在 4 旁边，是因为到了阶段 4 你已经有一个「会输出 PWM 的板子」，示波器才有东西可看。</li><li><strong>阶段 6 不是「学完四门课才能碰」。</strong> 专题是按「要造出什么」组织的，每个项目页开头就列出了前置章节；你可以从项目倒着补前置，这恰恰是三条路线里的「做项目」路线。</li></ol><h2 id="三条路线怎么选" tabindex="-1">三条路线怎么选 <a class="header-anchor" href="#三条路线怎么选" aria-label="Permalink to &quot;三条路线怎么选&quot;">​</a></h2><p>同一份内容，三种人的读法完全不同。<strong>先把路线定下来，再谈读哪几页</strong>，否则很容易陷在「每页都点开看一眼」的假进度里。</p><table tabindex="0"><thead><tr><th>路线</th><th>适合谁</th><th>怎么挑内容</th><th>预计</th><th>终点</th></tr></thead><tbody><tr><td><strong>考试 / 速通</strong></td><td>一周内要考、临时要用某个知识点</td><td>每门课只读核心章 + 每章「结论先行」「考点速记」，跳过演示与项目</td><td>电工学约 6.5 h、数电约 4 h、模电约 4.5 h，合计 15 h 上下</td><td>能做题、能答题，不求动手</td></tr><tr><td><strong>系统学</strong></td><td>第一次学、要能自己算与解释</td><td>四门课按 01 → 最后一章顺序读完，每章做演示、做例题</td><td>电工学约 12 h、数电约 6 h、模电约 7.5 h、嵌入式约 10 h，合计 35 h 上下</td><td>能算、能讲清因果</td></tr><tr><td><strong>做项目</strong></td><td>手上已经有板子或舵机，想先做出东西</td><td>直接从专题挑一个项目，按页面顶部的「前置章节」回头补</td><td>单项目 6–12 h，含补前置</td><td>有一台能开机的东西</td></tr></tbody></table><p>三条路线共享同一个<strong>兜底机制</strong>：每章正文里的前置胶囊（比如「戴维南 / 诺顿定理」「时间常数 τ」）点开就是一张卡片，先读一句摘要，看不懂再展开定义与常见坑。这意味着「做项目」路线不会因为缺一块知识就卡死——缺哪块点哪块，比从头补课快得多。</p><div class="tip custom-block"><p class="custom-block-title">速通路线要挑的就是这些核心章</p><ul><li><strong>电工学</strong>：01 电路模型 → 02 基尔霍夫 → 05 叠加与戴维南 → 08 相量 → 09 RLC 与阻抗 → 12 三相 → 16 异步电动机原理 → 17 机械特性 → 19 继电接触器。其余章节按「了解」读结论即可。</li><li><strong>数字电路</strong>：01 数制 → 02 卡诺图 → 04 组合逻辑 → 05 触发器 → 06 计数器。09 章 Verilog 与 FPGA 属加餐。</li><li><strong>模拟电子</strong>：01 半导体器件 → 02 基本放大 → 05 集成运放 → 07 信号运算 → 09 直流电源。03 频率响应与 06 反馈是「要能算」的门槛，速通时可先读结论。</li><li><strong>嵌入式</strong>：02 建工程 → 05 GPIO → 07 定时器 PWM → 08 串口 → 06 中断。11 RTOS 与 12 低功耗留到做项目时再读。</li></ul></div><h2 id="八个阶段-逐段拆开" tabindex="-1">八个阶段，逐段拆开 <a class="header-anchor" href="#八个阶段-逐段拆开" aria-label="Permalink to &quot;八个阶段，逐段拆开&quot;">​</a></h2><p>下面每一节都按同一个格式写：<strong>学什么 / 在哪个页面 / 大约多久 / 过关标准</strong>，外加<strong>前置检查</strong>（本站的前置胶囊 + 三个自问问题）、<strong>推荐网课入口</strong>与<strong>卡住时去哪</strong>。所有时长都是「第一次学、按时做演示」的估计，学过的人可以砍掉一半。</p><h3 id="阶段-0-·-电学入门与安全" tabindex="-1">阶段 0 · 电学入门与安全 <a class="header-anchor" href="#阶段-0-·-电学入门与安全" aria-label="Permalink to &quot;阶段 0 · 电学入门与安全&quot;">​</a></h3><p><strong>学什么</strong>：电压、电流、电阻、功率这几个量的物理意思；参考方向为什么必须先规定；欧姆定律与串并联；以及一件比前三者都重要的事——<strong>哪些动作会让你受伤</strong>。这一阶段不追求会算复杂电路，只求建立「电是能量，能量有边界」的基本直觉。</p><p><strong>在哪个页面</strong>：<a href="/ee/01-basics/model-reference">电工学 01 · 电路模型与参考方向</a> 与 <a href="/ee/01-basics/kcl-kvl">02 · 基尔霍夫定律与电位</a> 两页读结论部分即可；安全部分读 <a href="/lab/bench">实验台与安全</a> 的六条规则与 <a href="/ee/07-control/safety">电工学 21 · 安全用电</a>；仪器可以先看 <a href="/lab/">实验与仪器总览</a> 里「四类基础仪器」一节。</p><p><strong>大约多久</strong>：4–6 h。其中读页面约 2 h，剩下 3 h 建议直接花在第一次上手：万用表测电池、面包板点一个 LED、示波器测自身的校准方波。</p><p><strong>前置检查</strong>：本阶段没有硬前置。三个自问问题：① 如果我说「这个电阻上的电压是 5 V」，在不知道参考方向的情况下这句话完整吗？② 一只 1/4 W 的 220 Ω 电阻能承受多大电流？③ 断电以后，哪些地方还可能带高压？</p><p><strong>过关标准</strong>：能回答①②③；能在一个 5 V 电源上串电阻点亮 LED 并算出电流；能说出实验室里「先断电、再放电、再检查」这个顺序里每一步在防什么。做不出这三件事就回到 <a href="/lab/multimeter">/lab/multimeter</a> 的开头重读一遍接法。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里电工学的上半部分，只挑前几集「电路模型与参考方向」看，不要从头追到尾。</p><p><strong>卡住时去哪</strong>：概念记不住查 <a href="/guide/glossary">/guide/glossary</a> 的胶囊索引；万用表读数不对回 <a href="/lab/multimeter">/lab/multimeter</a> 看「虚电与接触电阻」；公式忘了开 <a href="/shared/cheatsheet">/shared/cheatsheet</a> 第 1 节。</p><h3 id="阶段-1-·-电工学-电路定律到三相与电机" tabindex="-1">阶段 1 · 电工学（电路定律到三相与电机） <a class="header-anchor" href="#阶段-1-·-电工学-电路定律到三相与电机" aria-label="Permalink to &quot;阶段 1 · 电工学（电路定律到三相与电机）&quot;">​</a></h3><p><strong>学什么</strong>：这是全站的骨架，也是时间最长的一段。直流部分：KCL/KVL、结点电压法、叠加定理与戴维南等效；动态部分：储能元件、换路定则、三要素法；交流部分：相量、阻抗、功率与功率因数、谐振；强电部分：三相电路、磁路与变压器、异步电动机、继电接触器与 PLC。核心是**「换一种表示法把问题化简」**这个反复出现的套路——戴维南是把整个网络折成两参数，相量是把微分方程折成复数代数，三相是把三根线折成一根等效线。</p><p><strong>在哪个页面</strong>：从 <a href="/ee/">电工学课程主页</a> 的章节路线进入，按 01 → 21 顺序读。三处必须停下来做演示的地方：<a href="/ee/04-ac/rlc">RLC 串联与阻抗</a>、<a href="/ee/05-three-phase/circuit">三相电路</a>、<a href="/ee/06-machine/motor-characteristic">机械特性与起动调速</a>。读完全部章节后去 <a href="/ee/graph">/ee/graph</a> 看一次依赖图，确认自己没有漏掉某条支线。</p><p><strong>大约多久</strong>：系统学约 12 h，速通约 6.5 h。建议拆成三周：第一周直流与暂态，第二周交流与功率，第三周磁路电机与控制。</p>`,26)),r("p",null,[a[0]||(a[0]=r("strong",null,"前置检查",-1)),a[1]||(a[1]=t("：前置胶囊主要挂 ",-1)),e(s,{id:"ohm"}),a[2]||(a[2]=t("、",-1)),e(s,{id:"kvl"}),a[3]||(a[3]=t("、",-1)),e(s,{id:"thevenin"}),a[4]||(a[4]=t("、",-1)),e(s,{id:"impedance"}),a[5]||(a[5]=t(" 这几张。三个自问问题：① 一个只有电阻和两个电源的电路，你能在五分钟内用戴维南等效求出某一支路电流吗？② 一阶电路的终值一定等于电源电压吗？③ 三相四线制里中性线电流为什么可能不为零？",-1))]),a[24]||(a[24]=o('<p><strong>过关标准</strong>：能独立解一道含受控源的直流电路题；能用三要素法一次写出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>u</mi><mi>C</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">u_C(t)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 并正确判断换路瞬间的值；能把正弦电路翻译成相量并算出功率因数；能解释转差率为什么必须大于零、电动机才出力。四道里错两道以上，就回到对应章节的「结论先行」重读，别急着往下走。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里哈工大姜三勇《电工学》上半（电路定律到三相）与下半（磁路电机与控制）。配合方式：先读本站结论，再看视频推一遍，回来做例题。</p><p><strong>卡住时去哪</strong>：忘了某个定理的名字与适用条件，去 <a href="/shared/cheatsheet">/shared/cheatsheet</a> 按主题搜；不知道某章该不该跳过，看 <a href="/ee/graph">/ee/graph</a> 与 <a href="/guide/status">/guide/status</a>；推导卡在数学上（复数、相量）翻 <a href="/guide/glossary">/guide/glossary</a> 里的「复数与相量运算」卡片。</p><h3 id="阶段-2-·-数字电路" tabindex="-1">阶段 2 · 数字电路 <a class="header-anchor" href="#阶段-2-·-数字电路" aria-label="Permalink to &quot;阶段 2 · 数字电路&quot;">​</a></h3><p><strong>学什么</strong>：数制与补码、布尔代数与卡诺图、TTL/CMOS 门电路、组合逻辑设计、触发器与时序分析、计数器与寄存器、存储器与可编程逻辑，最后把数字系统与模拟世界接起来（AD/DA 与 PWM），并知道 Verilog 与 FPGA 在做什么。核心不是电路图本身，而是<strong>状态与约束</strong>：组合逻辑只关心此刻，时序逻辑关心上一拍，时序图里那些竖线就是约束。</p><p><strong>在哪个页面</strong>：从 <a href="/digital/">数字电路课程主页</a> 进入，9 节正文。必须亲自动手的三处：<a href="/digital/boolean-kmap">卡诺图</a>（圈组规则要变成手上动作）、<a href="/digital/flip-flops">触发器</a>（波形演示能让你看见建立保持时间错在哪）、<a href="/digital/ad-da">AD/DA 与脉冲调制</a>（这一步之后才接得上嵌入式）。第 07 章 <a href="/digital/memory-pld">存储器与 PLD</a> 与第 09 章 <a href="/digital/09-verilog-fpga">Verilog 与 FPGA</a> 可以在做项目时回来补。</p><p><strong>大约多久</strong>：系统学约 6 h，速通约 4 h。数电是全站性价比最高的一门——概念少、反馈快，能把卡诺图练熟的话一周内可以吃透。</p>',7)),r("p",null,[a[6]||(a[6]=r("strong",null,"前置检查",-1)),a[7]||(a[7]=t("：前置胶囊有 ",-1)),e(s,{id:"boolean"}),a[8]||(a[8]=t("、",-1)),e(s,{id:"kmap"}),a[9]||(a[9]=t("、",-1)),e(s,{id:"flip-flop"}),a[10]||(a[10]=t("。三个自问问题：① 补码为什么能统一加减法？② 卡诺图里两格只差一位，为什么可以合并？③ 一个 4 位二进制计数器，最高位频率是输入时钟的几分之一？",-1))]),a[25]||(a[25]=o('<p><strong>过关标准</strong>：能把一个真值表在十分钟内化简成最简与或式；能画出一个三位计数器的时序图并说出模值；能解释 CMOS 输入为什么不能悬空、三态门为什么能挂总线；能说清采样定理与 PWM 的关系。任一题只能背答案不能推，就回到对应章节再做一遍演示。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里华北电力大学童话老师那套《数字电子技术基础》。它的课后题精讲只有 6.9 小时，适合「课听懂了但化简全错」的情况，边做边对。</p><p><strong>卡住时去哪</strong>：化简总错回 <a href="/digital/boolean-kmap">02 逻辑代数与卡诺图</a>；时序波形看不懂回 <a href="/digital/flip-flops">05 触发器</a>；想直接查门电路的逻辑符号与真值表，<a href="/shared/cheatsheet">/shared/cheatsheet</a> 的「时序与逻辑」一节有表。</p><h3 id="阶段-3-·-模拟电子" tabindex="-1">阶段 3 · 模拟电子 <a class="header-anchor" href="#阶段-3-·-模拟电子" aria-label="Permalink to &quot;阶段 3 · 模拟电子&quot;">​</a></h3><p><strong>学什么</strong>：二极管与三极管、三种组态的基本放大电路、频率响应与波特图、功率放大、集成运放、反馈的四种组态、信号运算与波形发生、以及直流电源。模电的难不在概念多，而在<strong>一张曲线图上三四个量同时动</strong>：工作点、负载线、增益、带宽互相牵制。学这一门的正确姿势是先建立图像，再推公式。</p><p><strong>在哪个页面</strong>：从 <a href="/analog/">模拟电子课程主页</a> 进入，10 节正文。关键节点：<a href="/analog/semiconductor">半导体器件</a>（先看特性曲线）、<a href="/analog/amplifiers">基本放大电路</a>（工作点与负载线）、<a href="/analog/opamp">集成运算放大电路</a>、<a href="/analog/dc-power">直流电源</a>。如果目标是做传感器采集，<a href="/analog/10-sensors">10 · 传感器与信号调理</a> 可以和 05、07 一起直读，它把前面九章的工具全部用在一条真实信号链上。</p><p><strong>大约多久</strong>：系统学约 7.5 h，速通约 4.5 h，只做传感器应用约 3 h。模电容易读得慢，建议每次只读一章，读完立刻去看对应的前置胶囊与演示，不要连读三章。</p>',7)),r("p",null,[a[11]||(a[11]=r("strong",null,"前置检查",-1)),a[12]||(a[12]=t("：前置胶囊主要是 ",-1)),e(s,{id:"diode"}),a[13]||(a[13]=t("、",-1)),e(s,{id:"bjt-regions"}),a[14]||(a[14]=t("、",-1)),e(s,{id:"q-point-loadline"}),a[15]||(a[15]=t("。三个自问问题：① 同一个三极管，静态工作点上移之后放大倍数一定变大吗？② 运放负反馈为什么能把输出「锁」在一个电压上？③ 线性稳压器从 24 V 降到 5 V、电流 2 A 时，有多少功率变成了热？",-1))]),a[26]||(a[26]=o('<p><strong>过关标准</strong>：能在特性曲线上画出负载线并读出工作点；能说出共射、共集、共基三种组态的输入输出阻抗量级与适用场合；能用深度负反馈估算闭环增益；能把整流—滤波—稳压串成一路直流并算出纹波与管耗。做不出来就回到 <a href="/analog/amplifiers">基本放大电路</a> 或 <a href="/analog/dc-power">直流电源</a> 的例题，把每一步数字代一遍。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里清华华成英《模拟电子技术基础》，优先看国家精品那条（画质清楚）。看之前先点开本站的工作点与负载线胶囊，「曲线 + 负载线」的图像建起来之后，视频会跟得上得多。</p><p><strong>卡住时去哪</strong>：看不懂某个元器件在干什么查 <a href="/guide/glossary">/guide/glossary</a>；波特图读不出来回 <a href="/analog/frequency">03 频率响应</a>；想做传感器但不知道从哪下手，去 <a href="/topics/power-supply">/topics/power-supply</a> 看一个完整的电源实例，再回来看模电的电源章。</p><h3 id="阶段-4-·-嵌入式-stm32" tabindex="-1">阶段 4 · 嵌入式 STM32 <a class="header-anchor" href="#阶段-4-·-嵌入式-stm32" aria-label="Permalink to &quot;阶段 4 · 嵌入式 STM32&quot;">​</a></h3><p><strong>学什么</strong>：从「看懂电路」到「让芯片干活」。开发环境与最小工程、寄存器思维、时钟树、GPIO 与按键、中断与 NVIC、定时器与 PWM、串口、SPI/I²C、ADC 与 DMA、FreeRTOS、低功耗，最后用第 13 章的舵机控制把所有这些拼成一个会动的执行器。</p><p><strong>在哪个页面</strong>：从 <a href="/embedded/">嵌入式课程主页</a> 进入，13 节正文。第 13 章 <a href="/embedded/13-servo-control">舵机控制：从 PWM 脉宽到角度</a> 是这门课的「第一个真正动起来的项目」，建议学完第 07 章定时器之后立刻读。前言里那句总结值得先记住：50 Hz、0.5–2.5 ms、1.5 ms 中位，舵机必须独立 5 V 供电并与 STM32 共地。</p><p><strong>大约多久</strong>：系统学约 10 h，速通约 5 h。但<strong>能否跟上不取决于读，而取决于有没有一块板</strong>：每学完一个外设就接一次线，总时长会拉长到 15 h 以上，但这是唯一能算过关的方式。</p>',7)),r("p",null,[a[16]||(a[16]=r("strong",null,"前置检查",-1)),a[17]||(a[17]=t("：前置胶囊有 ",-1)),e(s,{id:"register-map"}),a[18]||(a[18]=t("、",-1)),e(s,{id:"clock-tree"}),a[19]||(a[19]=t("、",-1)),e(s,{id:"nvic-priority"}),a[20]||(a[20]=t("、",-1)),e(s,{id:"dma-cache"}),a[21]||(a[21]=t("。三个自问问题：① 为什么新开的外设常常「配了参数却不工作」？② 中断优先级的抢占与子优先级在什么情况下会同时起作用？③ ADC 采到的值抖动，是硬件噪声还是参考电压问题？",-1))]),a[27]||(a[27]=o('<p><strong>过关标准</strong>：能从零建工程、点灯、串口打印、被中断打断；能算清 PSC/ARR/CCR 并让舵机转到指定角度且稳定不抖。最后这一条尤其关键——「代码全对但一直抖/一直复位」的根因几乎都在供电与地上，能自己查出来，这一阶段才算过。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里江协科技《STM32 入门教程 2023 版》，它讲「新建工程 → 写代码 → 下载看现象」，正好和本站的「先讲为什么」互补。舵机那一段在 P16，只看这一段也行。</p><p><strong>卡住时去哪</strong>：编译不过或下载失败回 <a href="/embedded/environment">02 开发环境与第一个工程</a>；时钟算错回 <a href="/embedded/clock">04 时钟系统</a>；通信不通回 <a href="/embedded/uart">08 串口</a> 与 <a href="/embedded/spi-i2c">09 SPI 与 I²C</a>。硬件层面的接线与读数问题去 <a href="/lab/">/lab/</a>，尤其是 <a href="/lab/oscilloscope">/lab/oscilloscope</a> 的「测 PWM 占空比」一节。</p><h3 id="阶段-5-·-实验与仪器-可与阶段-4-并行" tabindex="-1">阶段 5 · 实验与仪器（可与阶段 4 并行） <a class="header-anchor" href="#阶段-5-·-实验与仪器-可与阶段-4-并行" aria-label="Permalink to &quot;阶段 5 · 实验与仪器（可与阶段 4 并行）&quot;">​</a></h3><p><strong>学什么</strong>：万用表的四种接法为什么互斥、示波器的探头与地线为什么是电路的一部分、焊接与洞洞板工艺、实验台的强电弱电分区与排查顺序。这一阶段教的<strong>不是更多知识，而是怀疑</strong>：什么时候读数本身不可信。</p><p><strong>在哪个页面</strong>：<a href="/lab/">/lab/</a> 总览先读「六条直觉」与「第一次上手 3 小时清单」；然后按仪器分工读 <a href="/lab/multimeter">/lab/multimeter</a>、<a href="/lab/oscilloscope">/lab/oscilloscope</a>、<a href="/lab/soldering">/lab/soldering</a>、<a href="/lab/bench">/lab/bench</a>。四个页面按 45 + 50 + 45 + 40 分钟算，一共约 3 h，正好等于那张 3 小时清单。</p><p><strong>大约多久</strong>：3 h 读完，再加 3 h 实际动手。它可以拆散：读阶段 1 时练万用表，读阶段 4 时练示波器测 PWM，做阶段 6 之前练焊接。</p><p><strong>前置检查</strong>：没有前置胶囊要求，但有一个物理前置：<strong>桌面要有能用的插座与限流电源</strong>。三个自问问题：① 电压档并联、电流档串联，接反了会怎样？② 示波器的地线夹能不能夹在电路里任意一点？③ 面包板串行验证「电流处处相等」时，读数差在哪里？</p><p><strong>过关标准</strong>：能用万用表在 30 s 内判断一只三极管的管脚；能在示波器上读出 1 kHz、25% 占空比 PWM 的高电平时间；能焊出一个锥形、发亮、无残锡的焊点；能背出「断电 → 放 30 秒 → 放电 → 万用表验证 → 再分析」的顺序。</p><p><strong>推荐网课入口</strong>：仪器操作类内容不太需要跟整套课，<a href="/guide/courses">/guide/courses</a> 里没有专门的仪器课；建议直接用清单式练习——按 <a href="/lab/">/lab/</a> 的 3 小时清单从 0:00 做到 3:20，做完再看哪个判据没达到。</p><p><strong>卡住时去哪</strong>：读数跟手算差一个量级，先回 <a href="/lab/multimeter">/lab/multimeter</a> 的「虚电与接触电阻」；示波器波形全是毛刺，看 <a href="/lab/oscilloscope">/lab/oscilloscope</a> 的探头补偿与地线一节；任何一次冒烟或异响之后，先看 <a href="/lab/bench">/lab/bench</a> 的排查顺序，再分析原因。</p><h3 id="阶段-6-·-项目专题-电源-电机-舵机云台" tabindex="-1">阶段 6 · 项目专题（电源 / 电机 / 舵机云台） <a class="header-anchor" href="#阶段-6-·-项目专题-电源-电机-舵机云台" aria-label="Permalink to &quot;阶段 6 · 项目专题（电源 / 电机 / 舵机云台）&quot;">​</a></h3><p><strong>学什么</strong>：把前五个阶段的知识按「造出一台机器」重新组织。三个项目是一条递进的链：可调实验电源负责供能，直流电机驱动负责功率与时序，双轴舵机云台负责坐标与机械。每个页面都按同一条流水线写——方案对比、原理与公式、BOM、接线、代码、分步调试、故障排查表。</p><p><strong>在哪个页面</strong>：从 <a href="/topics/">/topics/</a> 总览进入。顺序建议严格按 <a href="/topics/power-supply">可调实验电源</a> → <a href="/topics/motor-drive">直流电机驱动</a> → <a href="/topics/servo-gimbal">双轴舵机云台</a>。理由不是玄学：电源是所有实验的地基，电机驱动那套「独立电源 + 共地 + 去耦」的接线纪律可以原样复刻到云台上，而云台 90% 的抖动问题出在供电。</p><p><strong>大约多久</strong>：电源 6–10 h，电机驱动 8–12 h，云台 6–8 h。三个全做约 20–30 h，但可以只做一个。项目页里的时间不含「补前置章节」，实际第一次做通常要再加 3–5 h。</p><p><strong>前置检查</strong>：三个项目各有明确的前置章节，页面顶部都列了。做电源前读 <a href="/ee/08-electronics/rectifier">电工学 22 · 整流滤波稳压</a> 与 <a href="/analog/dc-power">模电 09 · 直流电源</a>；做电机驱动前读 <a href="/embedded/timer-pwm">嵌入式 07 · 定时器与 PWM</a> 与 <a href="/embedded/adc-dma">10 · ADC 与 DMA</a>；做云台前读 <a href="/embedded/13-servo-control">嵌入式 13 · 舵机控制</a>。三个自问问题：① 我的电源限流设在哪里，带载时跌了多少伏？② H 桥四个开关同时倒向同一侧会发生什么？③ 舵机堵转电流是开发板 LDO 额定电流的多少倍？</p><p><strong>过关标准</strong>：说出<strong>自己机器上的实测数字</strong>，而不是页面上的推荐值。电源要报出空载与满载电压、纹波毫伏数、限流点；电机驱动要报出正反转、调速曲线与编码器测速误差；云台要报出两个轴的角度误差与连续运行 10 分钟不抖。没有数字就算没做完——「能转」不是通过条件。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里江协科技 P16 与陈加油嗯的舵机单集，都适合在做云台时边做边看。电源与电机驱动没有对应的完整网课，以项目页与前置章节为准。</p><p><strong>卡住时去哪</strong>：电源纹波大或发烫，看 <a href="/topics/power-supply">/topics/power-supply</a> 的故障排查表，再回 <a href="/topics/power-electronics/ac-dc">电力电子 AC-DC</a> 核纹波公式；电机一启动单片机就复位，多半是供电，去 <a href="/lab/bench">/lab/bench</a> 复习限流与共地；云台抖动，先查供电再看 <a href="/lab/oscilloscope">/lab/oscilloscope</a> 的 PWM 占比测量，确认脉宽本身对不对。</p><h3 id="阶段-7-·-电力电子与进阶" tabindex="-1">阶段 7 · 电力电子与进阶 <a class="header-anchor" href="#阶段-7-·-电力电子与进阶" aria-label="Permalink to &quot;阶段 7 · 电力电子与进阶&quot;">​</a></h3><p><strong>学什么</strong>：把前面所有「电压波形是给定的」这个假设去掉。用开关做能量变换：AC-DC 整流、DC-DC 升降压、DC-AC 逆变，以及器件（二极管、MOSFET、IGBT）的适用区间与损耗模型。到这里，失真、纹波、谐波、损耗、发热才是主角。</p><p><strong>在哪个页面</strong>：从 <a href="/topics/power-electronics/">电力电子入门 · 课程导览</a> 开始，它只回答一个问题：什么时候该翻开这门课。然后按 <a href="/topics/power-electronics/ac-dc">AC-DC</a> → <a href="/topics/power-electronics/dc-dc">DC-DC</a> → <a href="/topics/power-electronics/dc-ac">DC-AC</a> 的顺序读。更远的进阶方向（CAN、USB、以太网、嵌入式 Linux）本站暂不覆盖，<a href="/embedded/">/embedded/</a> 末尾的「暂不涉及」一节已经写明边界。</p><p><strong>大约多久</strong>：导览约 20 min，三页正文各 50–55 min，合计约 3 h。这一阶段可以反复回来，不必一次读完。</p><p><strong>前置检查</strong>：前置主要是 <a href="/ee/05-three-phase/power">三相与功率因数</a>、<a href="/analog/power-amp">模电 04 · 功率放大</a> 与 <a href="/analog/feedback">模电 06 · 反馈</a>。三个自问问题：① 为什么 Boost 的输出永远高于输入？② 死区时间如果设成零会发生什么？③ 线性稳压器与 Buck 在 24 V 到 5 V、2 A 时的管耗差多少？</p><p><strong>过关标准</strong>：能用占空比公式算出一个 Buck 的输出电压与电感取值；能说清整流电路留下的两个烂摊子（纹波与低功率因数）；能解释逆变器「母线电压固定、输出幅值连续可调」这个矛盾是怎么用调制比解决的。</p><p><strong>推荐网课入口</strong>：<a href="/guide/courses">/guide/courses</a> 里没有专门讲电力电子的课；建议以本站三页正文与 <a href="/shared/cheatsheet">/shared/cheatsheet</a> 的功率与效率一节为主线，把例题的数字自己算一遍。</p><p><strong>卡住时去哪</strong>：公式里的符号与适用前提对不上，查 <a href="/shared/cheatsheet">/shared/cheatsheet</a>；想知道这些内容在整张图里的位置，回 <a href="/ee/graph">/ee/graph</a>；动手验证时的一切读数问题，回 <a href="/lab/">/lab/</a>。</p><h2 id="每阶段共用的三条去处" tabindex="-1">每阶段共用的三条去处 <a class="header-anchor" href="#每阶段共用的三条去处" aria-label="Permalink to &quot;每阶段共用的三条去处&quot;">​</a></h2><p>不管卡在哪个阶段，先按这个顺序找，比盲目翻页快：</p><ol><li><strong>这个词是什么意思</strong> → <a href="/guide/glossary">/guide/glossary</a>。全站 43 张前置卡片的索引，按概念直接搜，点开就地展开。</li><li><strong>公式忘了 / 单位不确定</strong> → <a href="/shared/cheatsheet">/shared/cheatsheet</a>。按主题分组，每条给了符号、SI 单位与适用前提；Ctrl/⌘ + F 直接搜关键词。</li><li><strong>手上有实物却测不准、接不对</strong> → <a href="/lab/bench">/lab/bench</a>。它给的是排查顺序，不是知识点解答——冒烟、异响、发烫、复位都从这里进。</li></ol><p>再往外一圈还有两个人手：<a href="/guide/courses">/guide/courses</a> 找网课，<a href="/guide/status">/guide/status</a> 确认某章写到什么程度（哪节能当教材读、哪节还只是提纲）。最后，<a href="/guide/pages">/guide/pages</a> 是全部页面的完整索引，适合「想不起来在哪见过」的时候。</p><h2 id="我该从哪开始" tabindex="-1">我该从哪开始 <a class="header-anchor" href="#我该从哪开始" aria-label="Permalink to &quot;我该从哪开始&quot;">​</a></h2><p>按目标选一行，不要按「我应该学什么」选。下表里的时长是「到能交付」的估计，不含休息。</p><table tabindex="0"><thead><tr><th>我的目标</th><th>起点</th><th>路线</th><th>主要页面</th><th>预计</th></tr></thead><tbody><tr><td>零基础，想系统学一遍电学</td><td>阶段 0</td><td>系统学</td><td><a href="/ee/">/ee/</a> → <a href="/digital/">/digital/</a> → <a href="/analog/">/analog/</a> → <a href="/embedded/">/embedded/</a></td><td>35 h+</td></tr><tr><td>一周内要考电工学</td><td>阶段 1</td><td>考试速通</td><td><a href="/ee/">/ee/</a> 核心章 + <a href="/shared/cheatsheet">/shared/cheatsheet</a></td><td>6.5 h</td></tr><tr><td>一周内要考数电 / 模电</td><td>阶段 2 或 3</td><td>考试速通</td><td><a href="/digital/">/digital/</a> 或 <a href="/analog/">/analog/</a> + 速查表</td><td>4–4.5 h</td></tr><tr><td>学过但忘了，只想补漏</td><td>阶段 1</td><td>系统学（跳读）</td><td><a href="/ee/graph">/ee/graph</a> 找卡点 → 对应章节</td><td>按需</td></tr><tr><td>手上只有一块 STM32，想让它动起来</td><td>阶段 4</td><td>做项目</td><td><a href="/embedded/">/embedded/</a> 07 → 13，配 <a href="/lab/">/lab/</a></td><td>8–12 h</td></tr><tr><td>想做一台桌面电源</td><td>阶段 6</td><td>做项目</td><td><a href="/topics/power-supply">/topics/power-supply</a> + 补齐前置</td><td>6–10 h</td></tr><tr><td>想做能正反转调速的电机</td><td>阶段 6</td><td>做项目</td><td><a href="/topics/motor-drive">/topics/motor-drive</a> + 补齐前置</td><td>8–12 h</td></tr><tr><td>想做双轴舵机云台</td><td>阶段 6</td><td>做项目</td><td><a href="/topics/servo-gimbal">/topics/servo-gimbal</a> + <a href="/embedded/13-servo-control">嵌入式 13</a></td><td>6–8 h</td></tr><tr><td>想把纸面结论拿仪器验一遍</td><td>阶段 5</td><td>任意</td><td><a href="/lab/">/lab/</a> 的 3 小时清单</td><td>3–6 h</td></tr><tr><td>想搞明白开关电源怎么工作</td><td>阶段 7</td><td>系统学</td><td><a href="/topics/power-electronics/">/topics/power-electronics/</a> 三页</td><td>3 h</td></tr><tr><td>只是查一个词或一条公式</td><td>—</td><td>任意</td><td><a href="/guide/glossary">/guide/glossary</a>、<a href="/shared/cheatsheet">/shared/cheatsheet</a></td><td>5 min</td></tr></tbody></table><p>用这张表的方式是：先找到最像自己现状的那一行，只读它列出的页面，<strong>不要顺手点开别的</strong>。等这一行交付了，再回到上面找下一行——地图的价值在于少走弯路，不在于一次看全。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>想确认每门课的分级与时长：<a href="/ee/">电工学</a>、<a href="/digital/">数字电路</a>、<a href="/analog/">模拟电子</a>、<a href="/embedded/">嵌入式</a> 四张课程主页</li><li>想直接看动手板块：<a href="/lab/">实验与仪器</a></li><li>想直接看项目：<a href="/topics/">项目专题</a></li><li>想知道本站在哪些地方还写得薄：<a href="/guide/status">/guide/status</a></li></ul>',37))])}const T=l(h,[["render",g]]);export{C as __pageData,T as default};
